// components/LoginScreen.js  — Google sign-in gate
import { useState } from "react";
import { signInWithPopup, GoogleAuthProvider } from "firebase/auth";
import { auth } from "../utils/firebase";

export function LoginScreen() {
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState("");

  async function handleGoogle() {
    setLoading(true);
    setError("");
    try {
      await signInWithPopup(auth, new GoogleAuthProvider());
      // onAuthStateChanged in App.js picks this up automatically
    } catch (e) {
      setError(e.code === "auth/popup-closed-by-user"
        ? "Sign-in cancelled."
        : e.message || "Sign-in failed.");
      setLoading(false);
    }
  }

  return (
    <div style={{minHeight:"100vh",background:"var(--bg,#0f0f0c)",display:"flex",
      alignItems:"center",justifyContent:"center",padding:20}}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:wght@800&family=DM+Mono:wght@400;500&display=swap');
        *{box-sizing:border-box;margin:0;padding:0;}body{background:var(--bg,#0f0f0c);}
        @keyframes fadeUp{from{opacity:0;transform:translateY(20px)}to{opacity:1;transform:translateY(0)}}
        .google-btn:hover{opacity:0.88;}
        .google-btn:active{transform:scale(0.97);}
      `}</style>
      <div style={{width:"100%",maxWidth:320,animation:"fadeUp 0.4s ease",
        display:"flex",flexDirection:"column",alignItems:"center",gap:0}}>

        {/* Logo */}
        <div style={{textAlign:"center",marginBottom:36}}>
          <div style={{fontSize:56,marginBottom:14}}>🥫</div>
          <div style={{fontFamily:"Fraunces,serif",fontSize:30,fontWeight:800,
            color:"var(--accent,#f5c842)",letterSpacing:-0.5}}>Pantry</div>
          <div style={{fontSize:12,color:"var(--text-dim,#5a5848)",marginTop:6,
            fontFamily:"DM Mono,monospace"}}>Track what you have. Share with your household.</div>
        </div>

        {/* Google button */}
        <button
          className="google-btn"
          onClick={handleGoogle}
          disabled={loading}
          style={{
            width:"100%",display:"flex",alignItems:"center",justifyContent:"center",
            gap:12,padding:"13px 20px",
            background:"#fff",border:"none",borderRadius:12,
            fontFamily:"DM Mono,monospace",fontSize:14,fontWeight:500,
            color:"#1a1a1a",cursor:loading?"wait":"pointer",
            transition:"opacity 0.15s, transform 0.1s",
            opacity:loading?0.7:1,
            boxShadow:"0 2px 8px rgba(0,0,0,0.35)",
          }}>
          {/* Google logo SVG */}
          {!loading ? (
            <svg width="20" height="20" viewBox="0 0 24 24">
              <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
              <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
              <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l3.66-2.84z"/>
              <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/>
            </svg>
          ) : (
            <span style={{display:"inline-block",
              border:"2px solid #ccc",borderTopColor:"#555",
              borderRadius:"50%",width:18,height:18,
              animation:"spin 0.7s linear infinite"}}/>
          )}
          {loading ? "Signing in…" : "Continue with Google"}
        </button>

        {error && (
          <div style={{marginTop:14,fontSize:12,color:"var(--red,#e55a42)",
            textAlign:"center",fontFamily:"DM Mono,monospace"}}>{error}</div>
        )}

        <div style={{marginTop:28,fontSize:11,color:"var(--text-dim,#5a5848)",
          textAlign:"center",fontFamily:"DM Mono,monospace",lineHeight:1.7}}>
          Your data is stored securely in Firebase<br/>and never shared with third parties.
        </div>
      </div>
    </div>
  );
}
