// App.js — root component
// Handles Firebase auth gate and wraps everything in the shared PantryProvider.
import { useState, useEffect } from "react";
import { onAuthStateChanged, signOut } from "firebase/auth";
import { auth }          from "./utils/firebase";
import { PantryProvider } from "./context/AppContext";
import { LoginScreen }   from "./components/LoginScreen";
import { PantryShell }   from "./features/PantryShell";

export default function App() {
  // undefined = still determining auth state, null = signed out, object = signed in
  const [currentUser, setCurrentUser] = useState(undefined);

  useEffect(() => {
    return onAuthStateChanged(auth, (user) => setCurrentUser(user ?? null));
  }, []);

  // Splash while Firebase resolves auth state
  if (currentUser === undefined) {
    return (
      <div style={{minHeight:"100vh",background:"#0f0f0c",display:"flex",
        alignItems:"center",justifyContent:"center"}}>
        <style>{`
          @keyframes spin{to{transform:rotate(360deg)}}
          @import url('https://fonts.googleapis.com/css2?family=Fraunces:wght@800&display=swap');
        `}</style>
        <div style={{textAlign:"center"}}>
          <div style={{fontSize:44,marginBottom:12}}>🥫</div>
          <div style={{fontFamily:"Fraunces,serif",fontSize:22,color:"#f5c842",marginBottom:16}}>Pantry</div>
          <div style={{width:24,height:24,border:"2px solid #333",borderTopColor:"#f5c842",
            borderRadius:"50%",animation:"spin 0.8s linear infinite",margin:"0 auto"}}/>
        </div>
      </div>
    );
  }

  if (!currentUser) {
    return <LoginScreen />;
  }

  return (
    <PantryProvider currentUser={currentUser} onSignOut={() => signOut(auth)}>
      <PantryShell />
    </PantryProvider>
  );
}
