// ─────────────────────────────────────────────────────────────────────────────
// hooks/useBarcodeScanner.js
// Wraps the BarcodeDetector API (native or polyfill) with cooldown and sound.
// The polyfill enables camera scanning on Firefox / Safari / desktop Chrome
// using ZXing under the hood; the hook degrades gracefully when no camera is
// connected or permission is denied.
// ─────────────────────────────────────────────────────────────────────────────
import "barcode-detector/polyfill";   // sets window.BarcodeDetector if absent
import { useEffect, useRef, useState } from "react";
import { playSound } from "../utils/sound";

/**
 * @param {Function} onDetected  — called with the raw barcode string
 * @param {boolean}  active      — start/stop the scanner
 * @param {React.MutableRefObject} sndOptsRef — ref to current settings object
 * @param {string}   cooldownKey — which settings key to read for cooldown duration
 */
export function useBarcodeScanner(onDetected, active, sndOptsRef, cooldownKey = "addScanCooldown") {
  const vRef         = useRef(null);
  const stRef        = useRef(null);
  const rafRef       = useRef(null);
  const detRef       = useRef(null);
  const lastRef      = useRef(null);
  const coolRef      = useRef(false);
  const coolStartRef = useRef(0);
  const coolDurRef   = useRef(0);
  const coolPctRef   = useRef(0);          // tracks last-set value to avoid extra renders
  const [cooldownPct,    setCooldownPct]    = useState(0);    // 0 = ready, 100 = just fired
  const [cameraAvailable, setCameraAvailable] = useState(null); // null=probing, true, false

  useEffect(() => {
    if (!active) { setCooldownPct(0); coolPctRef.current = 0; setCameraAvailable(null); return; }
    let cancelled = false;

    async function start() {
      try {
        detRef.current = new window.BarcodeDetector({
          formats: ["ean_13","ean_8","upc_a","upc_e","code_128","code_39","qr_code"],
        });
        const facing = sndOptsRef?.current?.scanCamera || "environment";
        const stream = await navigator.mediaDevices.getUserMedia({
          video: {
            facingMode: { ideal: facing },
            width:     { ideal: 1920 },
            height:    { ideal: 1080 },
            frameRate: { ideal: 60, min: 30 },
          },
        });
        if (cancelled) { stream.getTracks().forEach(t => t.stop()); return; }
        stRef.current = stream;
        if (vRef.current) { vRef.current.srcObject = stream; await vRef.current.play(); }
        setCameraAvailable(true);
        scan();
      } catch (e) {
        // Camera not connected, permission denied, or BarcodeDetector unavailable.
        setCameraAvailable(false);
        if (e.name !== "NotFoundError" && e.name !== "NotAllowedError") console.error(e);
      }
    }

    async function scan() {
      if (cancelled || !vRef.current || !detRef.current) return;

      // ── Update cooldown progress bar ──────────────────────────────────────
      if (coolRef.current) {
        const elapsed = Date.now() - coolStartRef.current;
        const pct = Math.max(0, Math.round((1 - elapsed / coolDurRef.current) * 100));
        if (pct !== coolPctRef.current) { coolPctRef.current = pct; setCooldownPct(pct); }
      } else if (coolPctRef.current !== 0) {
        coolPctRef.current = 0; setCooldownPct(0);
      }

      try {
        const codes = await detRef.current.detect(vRef.current);
        if (codes.length > 0 && !coolRef.current) {
          const code = codes[0].rawValue;
          if (code !== lastRef.current) {
            const snd      = sndOptsRef?.current || {};
            const cooldown = snd[cooldownKey] ?? snd.scanCooldown ?? 1000;
            lastRef.current    = code;
            coolRef.current    = true;
            coolStartRef.current = Date.now();
            coolDurRef.current   = cooldown;
            coolPctRef.current   = 100;
            setCooldownPct(100);
            playSound("scan", snd);
            onDetected(code);
            setTimeout(() => { coolRef.current = false; lastRef.current = null; }, cooldown);
          }
        }
      } catch {}
      rafRef.current = requestAnimationFrame(scan);
    }

    start();

    return () => {
      cancelled = true;
      cancelAnimationFrame(rafRef.current);
      if (stRef.current) stRef.current.getTracks().forEach(t => t.stop());
    };
  }, [active, onDetected, sndOptsRef, cooldownKey]);

  return { vRef, cooldownPct, cameraAvailable };
}
