// ─────────────────────────────────────────────────────────────────────────────
// context/AppContext.js
// ─────────────────────────────────────────────────────────────────────────────
import { createContext, useContext, useState, useEffect, useRef, useCallback } from "react";
import { K, DEFAULT_SETTINGS } from "../constants";
import { ld, sv }              from "../utils/storage";
import {
  createPantry, pushPantryData, pushOverlayData, updateItemInFirebase, subscribeToPantry,
  leavePantry  as fbLeavePantry,
  kickMember   as fbKickMember,
  sendInvite   as fbSendInvite,
  getPendingInvites, acceptInvite as fbAcceptInvite, declineInvite,
  subscribeToConnection, getUserRecord, saveUserRecord,
  objToItems, checkRTDBConnected,
} from "../utils/sync";
import { DB_URL } from "../utils/firebase";
import { mkHistory, uid, mergeItems } from "../utils/items";
import { playSound }                  from "../utils/sound";

const PantryContext = createContext(null);

export function usePantry() {
  const ctx = useContext(PantryContext);
  if (!ctx) throw new Error("usePantry must be used inside PantryProvider");
  return ctx;
}

export function PantryProvider({ children, currentUser, onSignOut }) {
  // ── Device identity ───────────────────────────────────────────────────────
  const deviceId = useRef((() => {
    let id = ld("pantry-device-id", null);
    if (!id) { id = uid(); sv("pantry-device-id", id); }
    return id;
  })()).current;

  // ── Persisted state ───────────────────────────────────────────────────────
  const [items,      setItemsRaw]  = useState(() => ld(K.items,    []));
  const [settings,   setSettings]  = useState(() => ({ ...DEFAULT_SETTINGS, ...ld(K.settings, {}) }));
  const [groceryOv,  setGroceryOv] = useState(() => ld(K.groceryOv,  {}));
  const [transferOv, setTransferOv]= useState(() => ld(K.transferOv, {}));

  // ── Shared pantry state ───────────────────────────────────────────────────
  const [pantryId,       setPantryId]       = useState(() => ld(K.pantryCode, null));
  const [pantryMembers,  setPantryMembers]  = useState({});
  const [pantryOwnerId,  setPantryOwnerId]  = useState(null);
  const [myName,         setMyName]         = useState(() => ld(K.myName, "") || currentUser?.displayName || "");
  const [syncStatus,     setSyncStatus]     = useState("idle");
  const [lastSyncTime,   setLastSyncTime]   = useState(null);
  const [lastSyncBy,     setLastSyncBy]     = useState(null);

  // ── Invite state ──────────────────────────────────────────────────────────
  const [pendingInvites, setPendingInvites] = useState([]);
  const [inviteEmail,    setInviteEmail]    = useState("");
  const [inviteStatus,   setInviteStatus]   = useState("idle"); // idle|sending|sent|error
  const [inviteErr,      setInviteErr]      = useState("");

  // ── UI state ──────────────────────────────────────────────────────────────
  const [tab,         setTabRaw]    = useState("pantry");
  const [prevTab,     setPrevTab]   = useState("pantry");
  const [mode,        setMode]      = useState("pantry");
  const [editItem,    setEditItem]  = useState(null);
  const [pantryView,  setPantryViewRaw] = useState(() => ld("pantry-view-pref", null) || settings.defaultPantryView || "compact");
  const [sortBy,      setSortByRaw]    = useState(() => ld("pantry-sort-pref", null) || settings.defaultSortBy || "name");
  const [filterCat,   setFilterCat]   = useState("All");
  const [search,      setSearch]      = useState("");
  const [toast,       setToast]       = useState(null);
  const [pendingConfirm, setPendingConfirm] = useState(null);
  const [historyItem, setHistoryItem] = useState(null);
  const [undoStack,   setUndoStack]   = useState([]);
  const [showUndoHistory,  setShowUndoHistory]  = useState(false);
  const [showSettingsSaved,setShowSettingsSaved] = useState(false);
  const [showGroceryExport,setShowGroceryExport] = useState(false);
  const [showImportModal,  setShowImportModal]   = useState(false);
  const [showAddSheet,     setShowAddSheet]      = useState(false);
  const [showQR,      setShowQR]     = useState(false);
  const [scanning,    setScanning]   = useState(false);
  const [scanStatus,  setScanStatus] = useState("idle");
  const [scanLocation,setScanLocation]=useState("kitchen");
  const [scanCard,    setScanCard]   = useState(null);
  const [pendingRm,   setPendingRm]  = useState([]);
  const [showRmReview,setShowRmReview]=useState(false);
  const [creating,    setCreating]   = useState(false);
  const [pushStatus,  setPushStatus] = useState("idle");

  const savedSettingsRef = useRef(JSON.stringify(settings));

  // ── Persistence ───────────────────────────────────────────────────────────
  function setItems(fn) {
    setItemsRaw(prev => {
      const next = typeof fn === "function" ? fn(prev) : fn;
      sv(K.items, next);
      return next;
    });
  }
  useEffect(() => { sv(K.settings,  settings);   }, [settings]);
  useEffect(() => { sv(K.groceryOv,  groceryOv);  }, [groceryOv]);
  useEffect(() => { sv(K.transferOv, transferOv); }, [transferOv]);
  useEffect(() => { sv(K.myName,    myName);      }, [myName]);
  useEffect(() => { sv("pantry-view-pref", pantryView); }, [pantryView]);
  useEffect(() => { sv("pantry-sort-pref", sortBy);     }, [sortBy]);

  function setPantryView(v) { setPantryViewRaw(v); sv("pantry-view-pref", v); }
  function setSortBy(v)     { setSortByRaw(v);     sv("pantry-sort-pref", v); }

  // ── Toast ─────────────────────────────────────────────────────────────────
  function showToast(msg, type = "success", action = null) {
    setToast({ msg, type, action });
    setTimeout(() => setToast(null), action ? 5000 : 3500);
  }
  function dismissToast() { setToast(null); }

  // ── Navigation ────────────────────────────────────────────────────────────
  function goTab(dest) {
    if (tab === "settings" && dest !== "settings") {
      const changed = JSON.stringify(settings) !== savedSettingsRef.current;
      if (changed) {
        withConfirm("confirmLeave", {
          icon:"⚠️", title:"Discard settings changes?",
          message:"You have unsaved changes. Leave without saving?",
          confirmLabel:"Discard", confirmColor:"#e55a42",
        }, () => {
          setSettings(JSON.parse(savedSettingsRef.current));
          setTabRaw(dest); setMode("pantry"); setEditItem(null);
        });
        return;
      }
    }
    if (dest === "settings") setPrevTab(tab);
    setTabRaw(dest); setMode("pantry"); setEditItem(null);
  }
  function setTab(t) { setTabRaw(t); }

  // ── Confirmation ──────────────────────────────────────────────────────────
  function withConfirm(settingKey, opts, action) {
    if (settings[settingKey] === false) { action(); return; }
    setPendingConfirm({ ...opts, action });
  }

  // ── Undo ──────────────────────────────────────────────────────────────────
  function pushUndo(label) {
    setUndoStack(prev => [
      { label, snapshot:{ items:[...items], groceryOv:{...groceryOv}, transferOv:{...transferOv} }, at:new Date().toISOString() },
      ...prev.slice(0, 29),
    ]);
  }
  function applyUndo(entry) {
    setItems(entry.snapshot.items);
    setGroceryOv(entry.snapshot.groceryOv);
    setTransferOv(entry.snapshot.transferOv || {});
    setUndoStack(prev => prev.filter(e => e.at !== entry.at));
    showToast("Undone!");
  }

  // ── Grocery helpers ───────────────────────────────────────────────────────
  const setGrocNeed   = (id, qty) =>
    setGroceryOv(prev => ({ ...prev, [id]: { ...(prev[id]||{}), neededQty:Math.max(1,qty) } }));
  const pinGrocery    = id =>
    setGroceryOv(prev => ({ ...prev, [id]: { ...(prev[id]||{}), pinned:true, excluded:false } }));
  const unpinGrocery  = (id, name="") => {
    withConfirm("confirmRemoveGrocery",
      { icon:"🛒", title:"Remove from grocery list?",
        message: name ? `"${name}" will be removed.` : "This item will be removed.",
        confirmLabel:"Remove", confirmColor:"#e77d00" },
      () => setGroceryOv(prev => ({ ...prev, [id]: { excluded:true } }))
    );
  };

  // ── Transfer helpers ──────────────────────────────────────────────────────
  const pinTransfer   = id => setTransferOv(prev => ({ ...prev, [id]: { ...(prev[id]||{}), pinned:true } }));
  const unpinTransfer = id => setTransferOv(prev => { const n={...prev}; delete n[id]; return n; });

  // ── Firebase pantry sync ──────────────────────────────────────────────────
  // Refs so the real-time callback always sees current values.
  const itemsRef    = useRef(items);
  const grocOvRef   = useRef(groceryOv);
  const trfOvRef    = useRef(transferOv);
  const myPushRef            = useRef(false); // true while we're mid-push (skip our own echo)
  const skipPushRef          = useRef(false); // true when setItems was called by a remote update
  const debounceRef          = useRef(null);
  const overlayDebounceRef   = useRef(null);

  useEffect(() => { itemsRef.current  = items;      }, [items]);
  useEffect(() => { grocOvRef.current = groceryOv;  }, [groceryOv]);
  useEffect(() => { trfOvRef.current  = transferOv; }, [transferOv]);

  // ── Sync activity log ─────────────────────────────────────────────────────
  const [syncLog, setSyncLog] = useState([]); // [{id,type,at,by,names,count}]
  function addSyncEvent(ev) {
    setSyncLog(prev => [{ id: uid(), ...ev }, ...prev].slice(0, 30));
  }

  // ── Session write counter ─────────────────────────────────────────────────
  // Counts Firebase RTDB writes this session (resets on page reload).
  // Firebase Spark plan limit is bandwidth-based (10 GB/month), not per-call,
  // but this counter gives visibility into write activity.
  const [sessionWrites, setSessionWrites] = useState(0);
  function bumpWrites() { setSessionWrites(n => n + 1); }

  // Load pantryId from Firebase user record on first sign-in
  useEffect(() => {
    if (!currentUser) return;
    getUserRecord(currentUser.uid).then(rec => {
      if (rec?.pantryId) {
        setPantryId(rec.pantryId);
        sv(K.pantryCode, rec.pantryId);
      }
    });
    // Check for pending invites
    getPendingInvites(currentUser.email).then(setPendingInvites);
  }, [currentUser?.uid]);

  // Real-time listener — fires on any change from any member
  useEffect(() => {
    if (!pantryId) return;
    const unsub = subscribeToPantry(pantryId, ({ items: remoteItems, groceryOv: rGrOv, transferOv: rTrOv, members, metadata }) => {
      // Skip if we just pushed (our own echo)
      if (myPushRef.current) return;

      // Detect what changed vs our current local state and log it
      const changedItems = remoteItems.filter(ri => {
        const local = itemsRef.current.find(li => li.id === ri.id);
        return !local || (ri.updatedAt && ri.updatedAt > (local.updatedAt || 0));
      });
      if (changedItems.length > 0) {
        const by = changedItems[0].updatedByName || changedItems[0].updatedBy || "Someone";
        addSyncEvent({
          type:  "received",
          at:    Date.now(),
          by,
          names: changedItems.map(i => i.name).filter(Boolean).slice(0, 4),
          count: changedItems.length,
        });
      }

      const merged     = mergeItems(itemsRef.current, remoteItems);

      // Merge overlays per-property so remote pins/excludes propagate even when
      // the local side has an entry for the same item.  Local takes precedence
      // on any property it has explicitly set (last-writer semantics per field).
      const allOvIds = new Set([...Object.keys(rGrOv), ...Object.keys(grocOvRef.current)]);
      const mergedGrOv = {};
      for (const id of allOvIds) {
        mergedGrOv[id] = { ...(rGrOv[id] || {}), ...(grocOvRef.current[id] || {}) };
      }

      const allTrIds = new Set([...Object.keys(rTrOv), ...Object.keys(trfOvRef.current)]);
      const mergedTrOv = {};
      for (const id of allTrIds) {
        mergedTrOv[id] = { ...(rTrOv[id] || {}), ...(trfOvRef.current[id] || {}) };
      }

      // Mark this as a remote-driven state change so the debounce push skips it.
      // Without this flag, setItems() would trigger the push effect and we'd
      // immediately echo the remote data back to Firebase (ping-pong).
      skipPushRef.current = true;
      setItems(merged);
      setGroceryOv(mergedGrOv);
      setTransferOv(mergedTrOv);
      setPantryMembers(members || {});
      if (metadata?.ownerId) setPantryOwnerId(metadata.ownerId);
      setLastSyncTime(Date.now());
      setSyncStatus(s => s === "syncing" ? s : "ok");
      setTimeout(() => setSyncStatus(s => s === "ok" ? "idle" : s), 3000);
    }, (error) => {
      // PERMISSION_DENIED fires when the user has been kicked (they're no longer
      // a member so the read rule denies access).
      console.warn("Pantry access lost:", error?.code);
      setPantryId(null);   sv(K.pantryCode, null);
      setPantryMembers({}); setPantryOwnerId(null);
      setSyncStatus("idle");
      showToast("You were removed from the shared pantry.", "error");
    });
    return () => unsub();
  }, [pantryId]);

  // Connection indicator + offline→online flush
  const wasOfflineRef = useRef(false);
  useEffect(() => {
    if (!pantryId) return;
    const unsub = subscribeToConnection(connected => {
      setSyncStatus(prev =>
        prev === "syncing" || prev === "pushing" ? prev
        : connected ? "idle" : "offline"
      );
      if (!connected) {
        wasOfflineRef.current = true;
      } else if (wasOfflineRef.current) {
        // Just came back online — push whatever localStorage has so nothing is lost.
        // Firebase RTDB auto-replays writes queued during the same session, but if the
        // page was refreshed while offline those queues are gone; localStorage is the source
        // of truth in that case.
        wasOfflineRef.current = false;
        myPushRef.current = true;
        setSyncStatus("syncing");
        pushPantryData(pantryId, itemsRef.current, grocOvRef.current, trfOvRef.current)
          .then(() => {
            setLastSyncTime(Date.now());
            setSyncStatus("ok");
            setTimeout(() => setSyncStatus(s => s === "ok" ? "idle" : s), 3000);
          })
          .catch(e => { console.error("reconnect push", e); setSyncStatus("idle"); })
          .finally(() => { setTimeout(() => { myPushRef.current = false; }, 800); });
      }
    });
    return () => unsub();
  }, [pantryId]);

  // Immediate overlay push when grocery/transfer overlay changes locally.
  // Declared BEFORE the debounced full-push so both effects run in declaration
  // order: this effect checks skipPushRef but does NOT clear it; the full-push
  // effect below clears it.  This means a remote-driven overlay change is
  // suppressed by both effects without double-clearing the flag.
  useEffect(() => {
    if (!pantryId || skipPushRef.current) return;
    clearTimeout(overlayDebounceRef.current);
    overlayDebounceRef.current = setTimeout(() => {
      myPushRef.current = true;
      pushOverlayData(pantryId, groceryOv, transferOv)
        .then(() => bumpWrites())
        .catch(e => console.error("overlay push", e))
        .finally(() => setTimeout(() => { myPushRef.current = false; }, 800));
    }, 200);
    return () => clearTimeout(overlayDebounceRef.current);
  }, [groceryOv, transferOv, pantryId]);

  // Debounced auto-push on LOCAL changes only.
  // skipPushRef is set to true when items/overlays changed due to a remote
  // Firebase update — we must not push that back or we create a ping-pong loop
  // where every member's received update triggers another full write.
  useEffect(() => {
    if (!pantryId) return;
    if (skipPushRef.current) {
      // Remote-driven change — skip push this cycle and clear the flag.
      skipPushRef.current = false;
      return;
    }
    clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(async () => {
      setPushStatus("pushing");
      myPushRef.current = true;
      try {
        await pushPantryData(pantryId, items, groceryOv, transferOv);
        setLastSyncTime(Date.now());
        bumpWrites();
      } catch (e) { console.error("auto-push", e); }
      setTimeout(() => { myPushRef.current = false; }, 800);
      setPushStatus("idle");
    }, 500);
    return () => clearTimeout(debounceRef.current);
  }, [items, groceryOv, transferOv, pantryId]);

  // ── Immediate single-item push (live updates) ─────────────────────────────
  // Called right after saveItem so the other household members see the change
  // without waiting for the 500ms debounced full-push.
  function pushItemNow(item) {
    if (!pantryId || !item?.id) return;
    myPushRef.current = true;
    addSyncEvent({
      type:  "pushed",
      at:    Date.now(),
      by:    item.updatedByName || currentUser?.displayName || "You",
      names: [item.name].filter(Boolean),
      count: 1,
    });
    updateItemInFirebase(pantryId, item)
      .then(() => bumpWrites())
      .catch(e => console.error("pushItemNow", e))
      .finally(() => setTimeout(() => { myPushRef.current = false; }, 800));
  }

  // ── Atomic delete + sync ─────────────────────────────────────────────────
  // Handles deletion entirely here so items AND overlays are pushed in one
  // Firebase write — no timing gap where other members receive the tombstone
  // but still see the old overlay entry.
  function syncDeleteItem(id) {
    const original = itemsRef.current.find(i => i.id === id);
    if (!original) return;

    // Compute all updated state up-front so we can push it atomically.
    let newItems;
    if (pantryId) {
      const tombstone = { ...original, deletedAt: Date.now(), updatedAt: Date.now() };
      newItems = itemsRef.current.map(i => i.id === id ? tombstone : i);
    } else {
      newItems = itemsRef.current.filter(i => i.id !== id);
    }
    const newGroceryOv = { ...grocOvRef.current }; delete newGroceryOv[id];
    const newTransferOv = { ...trfOvRef.current }; delete newTransferOv[id];

    // Prevent the debounced overlay + full-push effects from firing an echo
    // after the state updates below.  Set the flags synchronously before React
    // schedules the next render so the effects see them when they run.
    if (pantryId) {
      skipPushRef.current = true;
      myPushRef.current   = true;
    }

    // Update local state (also persists to localStorage via setItems wrapper).
    setItems(newItems);
    setGroceryOv(newGroceryOv);
    setTransferOv(newTransferOv);

    if (pantryId) {
      // One atomic write: tombstone + cleaned-up overlays arrive together for
      // every other member — no intermediate state where the item is gone from
      // items but the overlay pin still references it (or vice-versa).
      pushPantryData(pantryId, newItems, newGroceryOv, newTransferOv)
        .then(() => bumpWrites())
        .catch(e => console.error("syncDeleteItem push", e))
        .finally(() => setTimeout(() => { myPushRef.current = false; }, 800));
    }
  }

  // ── Manual push ───────────────────────────────────────────────────────────
  const doSync = useCallback(async () => {
    if (!pantryId) return;
    setSyncStatus("syncing");
    try {
      myPushRef.current = true;
      await pushPantryData(pantryId, items, groceryOv, transferOv);
      myPushRef.current = false;
      setLastSyncTime(Date.now());
      bumpWrites();
      setSyncStatus("ok");
      setTimeout(() => setSyncStatus(s => s === "ok" ? "idle" : s), 3000);
    } catch (e) {
      console.error("doSync", e);
      myPushRef.current = false;
      setSyncStatus("error");
      setTimeout(() => setSyncStatus("idle"), 3000);
    }
  }, [pantryId, items, groceryOv, transferOv]);

  // ── Create shared pantry ──────────────────────────────────────────────────
  const [createErr, setCreateErr] = useState("");

  async function createSharedPantry() {
    if (creating) return;
    setCreating(true);
    setCreateErr("");
    try {
      // Step 1: verify the SDK can reach the database at all.
      // .info/connected fires with true as soon as the WebSocket is up —
      // no auth or rules required. If it never fires, the databaseURL is wrong
      // or the database simply doesn't exist yet.
      const connected = await checkRTDBConnected(6000);
      if (!connected) {
        throw new Error(
          `Cannot reach Firebase Realtime Database.\n\n` +
          `Current URL: ${DB_URL}\n\n` +
          `Check that:\n` +
          `1. The database exists — Firebase Console → Build → Realtime Database\n` +
          `2. The URL above matches the one shown in your Firebase console\n` +
          `   (non-US databases use a different URL format, e.g. …europe-west1.firebasedatabase.app)`
        );
      }

      // Step 2: attempt the write (with a safety-net timeout).
      const timeout = new Promise((_, reject) =>
        setTimeout(() => reject(new Error(
          "Write timed out — check your Realtime Database rules allow writes " +
          "for authenticated users when data doesn't exist yet (!data.exists())."
        )), 10000)
      );
      const id = await Promise.race([
        createPantry(currentUser, items, groceryOv, transferOv),
        timeout,
      ]);
      setPantryId(id);
      sv(K.pantryCode, id);
      setMyName(currentUser.displayName || "");
    } catch (e) {
      console.error("createPantry", e);
      setCreateErr(e.message || "Failed to create pantry.");
    } finally {
      setCreating(false);
    }
  }

  // ── Kick a member (owner only) ────────────────────────────────────────────
  function kickMember(targetUid, memberName) {
    withConfirm("confirmDelete",
      { icon: "🚫", title: `Remove ${memberName}?`,
        message: `${memberName} will be removed from the shared pantry immediately.`,
        confirmLabel: "Remove", confirmColor: "#e55a42" },
      async () => {
        try {
          await fbKickMember(pantryId, targetUid);
          setPantryMembers(prev => { const n = { ...prev }; delete n[targetUid]; return n; });
          showToast(`${memberName} removed.`);
        } catch (e) {
          console.error("kickMember", e);
          showToast("Failed to remove member: " + e.message, "error");
        }
      }
    );
  }

  // ── Leave shared pantry ───────────────────────────────────────────────────
  function leaveShared() {
    withConfirm("confirmLeave",
      { icon:"🚪", title:"Leave shared pantry?",
        message:"You'll keep your local items but won't sync with others anymore.",
        confirmLabel:"Leave", confirmColor:"#e55a42" },
      async () => {
        try {
          await fbLeavePantry(currentUser.uid, pantryId);
        } catch (e) { console.error("leavePantry", e); }
        setPantryId(null); sv(K.pantryCode, null);
        setPantryMembers({});
        setSyncStatus("idle");
      }
    );
  }

  // ── Invite by email ───────────────────────────────────────────────────────
  async function sendEmailInvite() {
    const email = inviteEmail.trim().toLowerCase();
    if (!email.includes("@")) { setInviteErr("Enter a valid email."); return; }
    if (email === currentUser?.email?.toLowerCase()) { setInviteErr("That's your own email."); return; }
    setInviteStatus("sending");
    setInviteErr("");
    try {
      await fbSendInvite(pantryId, myName || currentUser?.displayName || "Someone", email);
      setInviteStatus("sent");
      setInviteEmail("");
      setTimeout(() => setInviteStatus("idle"), 3000);
    } catch (e) {
      setInviteErr("Failed: " + e.message);
      setInviteStatus("error");
    }
  }

  // ── Accept / decline invite ───────────────────────────────────────────────
  const [acceptingId, setAcceptingId] = useState(null); // invite.id being accepted
  const [acceptErr,   setAcceptErr]   = useState({});   // { [invite.id]: message }

  async function acceptInvite(invite) {
    if (acceptingId) return;
    setAcceptingId(invite.id);
    setAcceptErr(prev => ({ ...prev, [invite.id]: null }));
    try {
      await fbAcceptInvite(invite.id, currentUser.email, currentUser, invite.pantryId);
      setPantryId(invite.pantryId);
      sv(K.pantryCode, invite.pantryId);
      setPendingInvites(prev => prev.filter(i => i.id !== invite.id));
      showToast("Joined pantry!");
    } catch (e) {
      console.error("acceptInvite", e);
      const msg = e.message?.includes("PERMISSION_DENIED")
        ? "Permission denied — update your Firebase Realtime Database rules (see firebase.js)."
        : (e.message || "Failed to join.");
      setAcceptErr(prev => ({ ...prev, [invite.id]: msg }));
    } finally {
      setAcceptingId(null);
    }
  }

  async function declineInviteById(invite) {
    try {
      await declineInvite(invite.id, currentUser.email);
      setPendingInvites(prev => prev.filter(i => i.id !== invite.id));
    } catch {}
  }

  // ── Save settings ─────────────────────────────────────────────────────────
  function saveSettings() {
    savedSettingsRef.current = JSON.stringify(settings);
    sv(K.settings, settings);
    setShowSettingsSaved(true);
    setTimeout(() => { setShowSettingsSaved(false); goTab(prevTab); }, 1200);
  }

  // ── Derived data ──────────────────────────────────────────────────────────
  const allItems = items
    .filter(i => !i.deletedAt)
    .map(i => ({ ...i, totalQty:(i.kitchenQty||0)+(i.storageQty||0) }));

  const expiringSoon = allItems.filter(i => {
    const d = Math.ceil((new Date(i.expiry) - new Date()) / 86400000);
    return i.expiry && d >= 0 && d <= (i.expiryWarnDays ?? settings.expiryWarnDays);
  });
  const expired = allItems.filter(i => {
    const d = Math.ceil((new Date(i.expiry) - new Date()) / 86400000);
    return i.expiry && d < 0;
  });
  const transferList = allItems.filter(i => {
    if (transferOv[i.id]?.pinned) return true;
    const kt = i.kitchenThreshold ?? settings.kitchenThreshold;
    return kt > 0 && i.kitchenQty <= kt && i.storageQty > 0;
  });
  const groceryList = allItems.filter(i => {
    const ov = groceryOv[i.id];
    if (ov?.excluded) return false;
    if (ov?.pinned)   return true;
    const tt = i.totalThreshold ?? settings.totalThreshold;
    return tt > 0 && i.totalQty <= tt;
  }).sort((a, b) => a.totalQty - b.totalQty);

  return (
    <PantryContext.Provider value={{
      // Identity
      deviceId, currentUser,
      // State
      items, setItems, settings, setSettings, groceryOv, setGroceryOv, transferOv, setTransferOv,
      pantryId, myName, setMyName,
      pantryMembers, pantryOwnerId, pendingInvites, acceptingId, acceptErr,
      inviteEmail, setInviteEmail, inviteStatus, inviteErr,
      syncStatus, setSyncStatus, lastSyncTime, lastSyncBy,
      pushStatus, creating, createErr, setCreateErr, syncLog, sessionWrites,
      tab, setTab, prevTab, mode, setMode,
      editItem, setEditItem,
      pantryView, setPantryView, sortBy, setSortBy,
      filterCat, setFilterCat, search, setSearch,
      toast, pendingConfirm, setPendingConfirm,
      historyItem, setHistoryItem,
      undoStack, setUndoStack, showUndoHistory, setShowUndoHistory,
      showSettingsSaved, setShowSettingsSaved,
      showGroceryExport, setShowGroceryExport,
      showImportModal, setShowImportModal,
      showAddSheet, setShowAddSheet,
      showQR, setShowQR,
      scanning, setScanning, scanStatus, setScanStatus,
      scanLocation, setScanLocation, scanCard, setScanCard,
      pendingRm, setPendingRm, showRmReview, setShowRmReview,
      savedSettingsRef,
      // Derived
      allItems, expiringSoon, expired, transferList, groceryList,
      // Actions
      goTab, showToast, dismissToast, withConfirm,
      pushUndo, applyUndo,
      setGrocNeed, pinGrocery, unpinGrocery,
      pinTransfer, unpinTransfer,
      doSync, pushItemNow, syncDeleteItem, createSharedPantry, leaveShared, kickMember,
      sendEmailInvite, acceptInvite, declineInviteById,
      saveSettings,
      onLock: onSignOut,
    }}>
      {children}
    </PantryContext.Provider>
  );
}
