// ─────────────────────────────────────────────────────────────────────────────
// utils/sync.js  — Firebase Realtime Database helpers
//
// Data is NOT encrypted — Firebase Auth + security rules protect access.
// Items are stored as an object (not array) keyed by item.id for granular
// real-time updates.  All writes use `update()` so concurrent edits on
// different fields never clobber each other.
// ─────────────────────────────────────────────────────────────────────────────
import { ref, get, set, update, remove, onValue, push } from "firebase/database";
import { db } from "./firebase";

// ── Helpers ───────────────────────────────────────────────────────────────────
/** Email → safe Firebase key (dots not allowed in keys). */
export function emailToKey(email) {
  return (email || "").toLowerCase().replace(/\./g, ",");
}

/** Convert items array to RTDB object keyed by item.id. */
function itemsToObj(items) {
  return Object.fromEntries((items || []).map(i => [i.id, i]));
}

/** Convert RTDB items object back to array. */
export function objToItems(obj) {
  return Object.values(obj || {});
}

/** Generate a random 6-character pantry code. */
export function genCode() {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  return Array.from({ length: 6 }, () => chars[Math.floor(Math.random() * chars.length)]).join("");
}

// ── User node ─────────────────────────────────────────────────────────────────
export async function getUserRecord(uid) {
  const snap = await get(ref(db, `users/${uid}`));
  return snap.exists() ? snap.val() : null;
}

export async function saveUserRecord(uid, data) {
  await update(ref(db, `users/${uid}`), data);
}

// ── Pantry CRUD ───────────────────────────────────────────────────────────────

/**
 * Create a new shared pantry.  Uploads current items and adds the creator as
 * the first member.  Returns the new pantryId.
 *
 * No collision check — 6-char code has ~900M possibilities so the probability
 * is negligible.  Removing the pre-check also avoids needing read access to
 * pantries the user doesn't belong to yet.
 */
export async function createPantry(user, items, groceryOv, transferOv) {
  const pantryId = genCode();

  const now = Date.now();
  await set(ref(db, `pantries/${pantryId}`), {
    metadata: {
      ownerId:    user.uid,
      ownerName:  user.displayName || user.email,
      createdAt:  now,
    },
    members: {
      [user.uid]: {
        name:     user.displayName || user.email,
        email:    user.email,
        joinedAt: now,
      },
    },
    items:      itemsToObj(items),
    groceryOv:  groceryOv  || {},
    transferOv: transferOv || {},
  });

  await saveUserRecord(user.uid, { pantryId, name: user.displayName || "" });
  return pantryId;
}

/**
 * Push all pantry data (items + overlays) to Firebase.
 * Uses `update()` so metadata and members are left untouched.
 */
export async function pushPantryData(pantryId, items, groceryOv, transferOv) {
  await update(ref(db, `pantries/${pantryId}`), {
    items:      itemsToObj(items),
    groceryOv:  groceryOv  || {},
    transferOv: transferOv || {},
  });
}

/**
 * Push only the grocery and transfer overlays — no items.
 * Used for immediate overlay sync without re-sending the full item list.
 */
export async function pushOverlayData(pantryId, groceryOv, transferOv) {
  await update(ref(db, `pantries/${pantryId}`), {
    groceryOv:  groceryOv  || {},
    transferOv: transferOv || {},
  });
}

/**
 * Update a single item immediately — used for live quantity changes.
 */
export async function updateItemInFirebase(pantryId, item) {
  if (!pantryId || !item?.id) return;
  await set(ref(db, `pantries/${pantryId}/items/${item.id}`), item);
}

/**
 * Subscribe to all real-time changes in a pantry.
 * `onData({ items, groceryOv, transferOv, members, metadata })` fires on every change.
 * `onAccessLost(error)` fires when the listener is cancelled — e.g. the user was kicked
 * and no longer has read permission.
 * Returns an unsubscribe function.
 */
export function subscribeToPantry(pantryId, onData, onAccessLost) {
  if (!pantryId) return () => {};
  return onValue(
    ref(db, `pantries/${pantryId}`),
    (snap) => {
      if (!snap.exists()) return;
      const d = snap.val();
      onData({
        items:      objToItems(d.items),
        groceryOv:  d.groceryOv  || {},
        transferOv: d.transferOv || {},
        members:    d.members    || {},
        metadata:   d.metadata   || {},
      });
    },
    (error) => {
      if (onAccessLost) onAccessLost(error);
    }
  );
}

/**
 * Remove a member from a pantry (owner only — enforced by RTDB rules).
 */
export async function kickMember(pantryId, targetUid) {
  await remove(ref(db, `pantries/${pantryId}/members/${targetUid}`));
}

/** Remove the current user from a pantry and clear their user node's pantryId. */
export async function leavePantry(uid, pantryId) {
  await remove(ref(db, `pantries/${pantryId}/members/${uid}`));
  await update(ref(db, `users/${uid}`), { pantryId: null });
}

// ── Invites ───────────────────────────────────────────────────────────────────

/**
 * Send an email invite.  Stored under /invitesByEmail/{emailKey} so the
 * recipient can look it up by their own email without needing a query index.
 */
export async function sendInvite(pantryId, pantryOwnerName, invitedEmail) {
  const emailKey  = emailToKey(invitedEmail);
  const inviteRef = push(ref(db, `invitesByEmail/${emailKey}`));
  await set(inviteRef, {
    pantryId,
    invitedByName: pantryOwnerName,
    invitedEmail,
    createdAt: Date.now(),
    status:   "pending",
  });
  return inviteRef.key;
}

/** Get all pending invites for an email address. */
export async function getPendingInvites(email) {
  const emailKey = emailToKey(email);
  const snap = await get(ref(db, `invitesByEmail/${emailKey}`));
  if (!snap.exists()) return [];
  return Object.entries(snap.val())
    .filter(([, v]) => v.status === "pending")
    .map(([id, v]) => ({ id, ...v }));
}

/** Accept an invite: add user to pantry members and update their user record. */
export async function acceptInvite(inviteId, invitedEmail, user, pantryId) {
  const emailKey = emailToKey(invitedEmail);
  // Add to pantry members
  await update(ref(db, `pantries/${pantryId}/members/${user.uid}`), {
    name:     user.displayName || user.email,
    email:    user.email,
    joinedAt: Date.now(),
  });
  // Save pantryId to user record
  await saveUserRecord(user.uid, { pantryId, name: user.displayName || "" });
  // Mark invite as accepted
  await update(ref(db, `invitesByEmail/${emailKey}/${inviteId}`), { status: "accepted" });
}

/** Decline (delete) an invite. */
export async function declineInvite(inviteId, invitedEmail) {
  const emailKey = emailToKey(invitedEmail);
  await remove(ref(db, `invitesByEmail/${emailKey}/${inviteId}`));
}

// ── Firebase connection state ─────────────────────────────────────────────────
export function subscribeToConnection(onConnected) {
  return onValue(ref(db, ".info/connected"), (snap) => onConnected(snap.val() === true));
}

/**
 * Returns true if the SDK connects to RTDB within `ms` milliseconds.
 * `.info/connected` fires immediately with false when offline, and becomes
 * true once the WebSocket handshake succeeds — no auth/rules needed.
 *
 * Uses `let unsub = null` (not `const`) so there's no temporal dead zone if
 * onValue fires its callback synchronously before the assignment completes.
 * The actual unsubscribe is deferred via setTimeout(0) for the same reason.
 */
export function checkRTDBConnected(ms = 6000) {
  return new Promise((resolve) => {
    let done = false;
    let unsub = null;

    const timer = setTimeout(() => {
      done = true;
      if (unsub) unsub();
      resolve(false);
    }, ms);

    unsub = onValue(ref(db, ".info/connected"), (snap) => {
      if (snap.val() === true && !done) {
        done = true;
        clearTimeout(timer);
        // Defer so this runs after onValue returns and unsub is definitely assigned.
        setTimeout(() => { if (unsub) unsub(); }, 0);
        resolve(true);
      }
    });
  });
}
